    code: `; x86-64 CPU Register Dump
; Displays all general purpose register values
; nasm -f elf64 regdump.asm && ld regdump.o -o regdump

section .data
    rax_msg db "RAX: ", 0
    rbx_msg db "RBX: ", 0
    rcx_msg db "RCX: ", 0
    rdx_msg db "RDX: ", 0
    newline db 10, 0
    hex_chars db "0123456789ABCDEF", 0

section .bss
    hex_buffer resb 17          ; 16 hex chars + null

section .text
    global _start

_start:
    ; Save register values
    push rbx
    push rcx
    push rdx

    ; Print RAX
    lea rsi, [rax_msg]
    call print_string
    mov rdi, rax
    call print_hex
    call print_newline

    ; Print RBX
    lea rsi, [rbx_msg]
    call print_string
    pop rdi                     ; restore RBX value
    call print_hex
    call print_newline

    ; Exit
    mov rax, 60
    xor rdi, rdi
    syscall

print_string:
    ; Print null-terminated string at RSI
    mov rax, 1                  ; sys_write
    mov rdi, 1                  ; stdout
    mov rdx, 5                  ; length
    syscall
    ret

print_hex:
    ; Convert RDI to hex string
    lea rsi, [hex_buffer + 16]
    mov byte [rsi], 0           ; null terminator
    mov rcx, 16

.hex_loop:
    dec rsi
    mov rax, rdi
    and rax, 0xF
    lea rbx, [hex_chars]
    mov al, [rbx + rax]
    mov [rsi], al
    shr rdi, 4
    loop .hex_loop

    ; Print hex string
    mov rax, 1
    mov rdi, 1
    mov rdx, 16
    syscall
    ret

print_newline:
    lea rsi, [newline]
    mov rax, 1
    mov rdi, 1
    mov rdx, 1
    syscall
    ret`
