    code: `; x86-64 Linux TCP Port Scanner
; Scans ports using raw syscalls
; nasm -f elf64 portscan.asm && ld portscan.o -o portscan

section .data
    open_msg    db "Port OPEN: ", 0
    target_ip   dd 0x0100007f           ; 127.0.0.1 in network byte order
    
section .bss
    sockfd      resq 1
    sockaddr    resb 16
    port_num    resw 1

section .text
    global _start

_start:
    mov r12, 1                          ; start port
    mov r13, 1024                       ; end port

scan_loop:
    cmp r12, r13
    jg exit_program

    ; Create socket
    ; socket(AF_INET, SOCK_STREAM, 0)
    mov rax, 41                         ; sys_socket
    mov rdi, 2                          ; AF_INET
    mov rsi, 1                          ; SOCK_STREAM
    xor rdx, rdx
    syscall
    
    test rax, rax
    js next_port
    mov [sockfd], rax

    ; Build sockaddr_in structure
    lea rdi, [sockaddr]
    mov word [rdi], 2                   ; AF_INET
    
    ; Convert port to network byte order
    mov ax, r12w
    xchg al, ah
    mov [rdi + 2], ax                   ; port
    
    mov eax, [target_ip]
    mov [rdi + 4], eax                  ; IP address

    ; connect(sockfd, sockaddr, 16)
    mov rax, 42                         ; sys_connect
    mov rdi, [sockfd]
    lea rsi, [sockaddr]
    mov rdx, 16
    syscall

    ; Check if connection successful
    test rax, rax
    jnz close_sock

    ; Port is open - print message
    mov rax, 1                          ; sys_write
    mov rdi, 1                          ; stdout
    lea rsi, [open_msg]
    mov rdx, 11
    syscall

    ; Print port number (simplified)
    mov rax, r12
    ; (would need to convert to string here)

close_sock:
    mov rax, 3                          ; sys_close
    mov rdi, [sockfd]
    syscall

next_port:
    inc r12
    jmp scan_loop

exit_program:
    mov rax, 60                         ; sys_exit
    xor rdi, rdi
    syscall`
