    code: `; x86-64 Cryptographically Secure Random Generator
; Uses /dev/urandom for entropy
; nasm -f elf64 random.asm && ld random.o -o random

section .data
    urandom_path db "/dev/urandom", 0
    hex_chars    db "0123456789abcdef", 0
    newline      db 10

section .bss
    random_buf   resb 32                ; 32 bytes of random data
    hex_output   resb 65                ; 64 hex chars + newline
    fd           resq 1

section .text
    global _start

_start:
    ; Open /dev/urandom
    mov rax, 2                          ; sys_open
    lea rdi, [urandom_path]
    xor rsi, rsi                        ; O_RDONLY
    syscall
    
    test rax, rax
    js exit_error
    mov [fd], rax

    ; Read 32 random bytes
    mov rax, 0                          ; sys_read
    mov rdi, [fd]
    lea rsi, [random_buf]
    mov rdx, 32
    syscall

    ; Close file
    mov rax, 3                          ; sys_close
    mov rdi, [fd]
    syscall

    ; Convert to hex
    lea rsi, [random_buf]
    lea rdi, [hex_output]
    mov rcx, 32

convert_loop:
    movzx eax, byte [rsi]
    
    ; High nibble
    mov edx, eax
    shr edx, 4
    lea rbx, [hex_chars]
    mov dl, [rbx + rdx]
    mov [rdi], dl
    inc rdi
    
    ; Low nibble
    and eax, 0x0F
    mov al, [rbx + rax]
    mov [rdi], al
    inc rdi
    
    inc rsi
    loop convert_loop

    ; Add newline
    mov byte [rdi], 10

    ; Print result
    mov rax, 1                          ; sys_write
    mov rdi, 1                          ; stdout
    lea rsi, [hex_output]
    mov rdx, 65
    syscall

    ; Exit success
    mov rax, 60
    xor rdi, rdi
    syscall

exit_error:
    mov rax, 60
    mov rdi, 1
    syscall`
