            Console.WriteLine("    -> LoadLibraryW @ 0x" + loadLibAddr.ToString("X"));
            
            Console.WriteLine("\\n[5] Creating remote thread...");
            Console.WriteLine("    -> CreateRemoteThread(LoadLibraryW, dllPath)");
            
