    description: {
        ar: "مراقبة العمليات الجديدة في الوقت الحقيقي",
        en: "Monitor new processes in real-time"
    },
    language: "C++",
    code: `#include <iostream>
#include <windows.h>
#include <tlhelp32.h>
#include <set>
#include <string>

class ProcessMonitor {
    std::set<DWORD> knownProcesses;
    
public:
    void takeSnapshot() {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        PROCESSENTRY32 pe;
        pe.dwSize = sizeof(pe);
        
        if (Process32First(snap, &pe)) {
            do {
                if (knownProcesses.find(pe.th32ProcessID) == knownProcesses.end()) {
                    std::wcout << L"[NEW] PID: " << pe.th32ProcessID 
                               << L" - " << pe.szExeFile << std::endl;
                    knownProcesses.insert(pe.th32ProcessID);
                }
            } while (Process32Next(snap, &pe));
        }
        CloseHandle(snap);
    }
    
    void monitor(int intervalMs = 1000) {
        std::cout << "[*] Monitoring processes... Press Ctrl+C to stop" << std::endl;
        
        // Initial snapshot
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        PROCESSENTRY32 pe;
        pe.dwSize = sizeof(pe);
        
        if (Process32First(snap, &pe)) {
            do {
                knownProcesses.insert(pe.th32ProcessID);
            } while (Process32Next(snap, &pe));
        }
        CloseHandle(snap);
        
        while (true) {
            Sleep(intervalMs);
            takeSnapshot();
        }
    }
};

int main() {
    ProcessMonitor monitor;
    monitor.monitor(500);
    return 0;
}`
